using Client.Files.IService;
using Client.Files.IService.Models.Request;
using System.ComponentModel;

namespace Client.File.Test
{
    public class FileServiceTest
    {
        private IFileB2Service _fileService;

        public FileServiceTest(IFileB2Service fileService)
        {
            _fileService = fileService;
        }

        [Fact]
        [Description("проверка на создание файла")]
        public async void Createfile()
        {
            var createFile = await _fileService.UploadFile(new UploadFileRequest
            {
                fileName = "photo.jpg",
                base64 = ""
            });

            Assert.True(!string.IsNullOrWhiteSpace(createFile.Data.fileId));
        }

        [Fact]
        [Description("проверка на удаление файла")]
        public async void DeleteFile()
        {
            var deleteFile = await _fileService.DeleteFileVersion(new DeleteFileVersionRequest
            {
                fileId = "4_z75fdcd1a4022faad9ea60415_f112cbeb4ce288658_d20251209_m184440_c003_v0312016_t0024_u01765305880708",
                fileName = "photo.jpg"
            });

            Assert.Null(deleteFile.ErrorMessage);
        }
    }
}